      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";

/**
 * @title AAVE pool supply interface
 */
interface IPool {
  function supply(address asset, uint256 amount, address onBehalfOf, uint16 referralCode) external;
}

/**
 * @title UnityWallet AAVE proxy
 *
 * @author UnityWallet Team (app@unitywallet.com)
 */
contract UnityAaveProxy {
  IPool public immutable AAVE_POOL;

  constructor(IPool pool) {
    AAVE_POOL = pool;
  }

  function prepareSupply(IERC20 asset, uint256 fee, uint256 amount, address feeCollector) internal {
    uint256 totalAmount = amount + fee;
    require(fee * 100 <= totalAmount, "Fee cannot exceed 1% of amount");
    require(asset.allowance(msg.sender, address(this)) >= totalAmount, "Not enough allowance");
    require(asset.balanceOf(msg.sender) >= totalAmount, "Not enough balance");

    bool transferFromResult = asset.transferFrom(msg.sender, address(this), totalAmount);
    if (!transferFromResult) {
      revert("Can't take deposit amount");
    }
    if (fee > 0) {
      bool transferResult = asset.transfer(feeCollector, fee);
      if (!transferResult) {
        revert("Can't take fee");
      }
    }
    if (asset.allowance(address(this), address(AAVE_POOL)) < amount) {
      asset.approve(address(AAVE_POOL), type(uint256).max);
    }
  }

  function supply(address asset, uint256 fee, uint256 amount, address feeCollector) public {
    prepareSupply(IERC20(asset), fee, amount, feeCollector);
    AAVE_POOL.supply(address(asset), amount, msg.sender, 0);
  }

  function supplyWithPermit(
    address asset,
    uint256 fee,
    uint256 amount,
    address feeCollector,
    uint256 permitValue,
    uint256 deadline,
    uint8 permitV,
    bytes32 permitR,
    bytes32 permitS
  ) public {
    IERC20Permit(asset).permit(msg.sender, address(this), permitValue, deadline, permitV, permitR, permitS);
    supply(asset, fee, amount, feeCollector);
  }
}
